<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
type State = -1 | 0 | 1 | 2
type Mode = '' | 'add' | 'edit' | 'copy' | 'version'
interface NodeRow { nodeId:string; nodeNo:string; nodeType:number; description:string; stageNo:string; sequence:number }
interface PropertyRow { propertyNo:string; defaultValue:string; sequence:number; description:string; issueState:State; dataStamp:number }
interface ProcessRow { processNo:string; processVersion:string; processClass:number; processType:string; psNo:string; description:string; issueState:State; curVersion:number; tuningProcess:number; partialType:number; dataStamp:number; creator:string; createDate:string; reviser:string; reviseDate:string; nodes:NodeRow[]; links:Array<{fromNodeId:string;toNodeId:string;linkName:string}>; properties:PropertyRow[] }
interface Draft { processNo:string; processVersion:string; processClass:number|''; processType:string; psNo:string; description:string }
interface Envelope<T>{items?:T[];rows?:T[];data?:T[];detail?:string;message?:string;title?:string}
const props=withDefaults(defineProps<{apiBaseUrl:string;currentUserNo?:string;developmentPreview?:boolean}>(),{currentUserNo:'',developmentPreview:false})
const emit=defineEmits<{close:[]}>()
const mock=computed(()=>import.meta.env.DEV&&props.developmentPreview), storageKey='ymes.dev.prs104-process-basis.v1'
const states:Array<{value:State;label:string}>=[{value:0,label:'未核准'},{value:1,label:'簽核中'},{value:2,label:'已核准'},{value:-1,label:'不使用'}]
const classes=[{value:0,label:'Production'},{value:1,label:'Engineering'},{value:2,label:'Rework'},{value:3,label:'OS'}]
const segments=['DEV-ASSY','DEV-PACK','DEV-QC'], types=['DEV-STANDARD','DEV-OUTSOURCE','DEV-REWORK'], elements=['DEV-PROC-TEMP','DEV-PROC-ROUTE']
const seed:ProcessRow[]=[
{processNo:'DEV-PRS-100',processVersion:'01',processClass:0,processType:'DEV-STANDARD',psNo:'DEV-ASSY',description:'DEV 標準組裝流程；未核准，可編輯流程圖',issueState:0,curVersion:0,tuningProcess:0,partialType:0,dataStamp:3,creator:'DEV001',createDate:'2026-11-12T08:30:00',reviser:'DEV001',reviseDate:'2026-11-17T14:10:00',nodes:[{nodeId:'N1',nodeNo:'START',nodeType:8,description:'開始',stageNo:'',sequence:1},{nodeId:'N2',nodeNo:'OP-ASSY',nodeType:0,description:'DEV 組裝',stageNo:'DEV-ASSY',sequence:2},{nodeId:'N3',nodeNo:'OP-QC',nodeType:0,description:'DEV 檢查',stageNo:'DEV-QC',sequence:3},{nodeId:'N4',nodeNo:'END',nodeType:9,description:'結束',stageNo:'',sequence:4}],links:[],properties:[{propertyNo:'DEV-PROC-TEMP',defaultValue:'25',sequence:1,description:'DEV 溫度條件',issueState:0,dataStamp:0}]},
{processNo:'DEV-PRS-200',processVersion:'02',processClass:3,processType:'DEV-OUTSOURCE',psNo:'DEV-PACK',description:'DEV 外包流程目前版本',issueState:2,curVersion:1,tuningProcess:0,partialType:0,dataStamp:6,creator:'DEV002',createDate:'2026-10-20T10:00:00',reviser:'DEV002',reviseDate:'2026-11-01T16:00:00',nodes:[{nodeId:'X1',nodeNo:'START',nodeType:8,description:'開始',stageNo:'',sequence:1},{nodeId:'X2',nodeNo:'OP-PACK',nodeType:0,description:'DEV 包裝',stageNo:'DEV-PACK',sequence:2},{nodeId:'X3',nodeNo:'END',nodeType:9,description:'結束',stageNo:'',sequence:3}],links:[],properties:[]},
{processNo:'DEV-PRS-200',processVersion:'01',processClass:3,processType:'DEV-OUTSOURCE',psNo:'DEV-PACK',description:'DEV 舊版本',issueState:2,curVersion:0,tuningProcess:0,partialType:0,dataStamp:2,creator:'DEV001',createDate:'2026-09-01T09:00:00',reviser:'DEV002',reviseDate:'2026-10-20T10:00:00',nodes:[],links:[],properties:[]}]
const rows=ref<ProcessRow[]>([]), state=ref<State>(0), keyword=ref(''), activeKey=ref(''), selected=ref<string[]>([])
const editor=ref(false),mode=ref<Mode>(''),sourceKey=ref(''),draft=ref<Draft>(blank())
const graph=ref(false),graphNodes=ref<NodeRow[]>([]),graphLinks=ref<Array<{fromNodeId:string;toNodeId:string;linkName:string}>>([]),properties=ref(false),propertyRows=ref<PropertyRow[]>([]),propertyDraft=ref<PropertyRow|null>(null),propertySource=ref('')
const importing=ref(false),fileName=ref(''),importMessage=ref(''),excluding=ref(false),busy=ref(false),error=ref(''),notice=ref('')
function blank():Draft{return{processNo:'',processVersion:'01',processClass:0,processType:'',psNo:'',description:''}}
function key(r:Pick<ProcessRow,'processNo'|'processVersion'>):string{return r.processNo+'\u001f'+r.processVersion}
function copy<T>(v:T):T{return JSON.parse(JSON.stringify(v)) as T}
function userNo():string{return props.currentUserNo||(mock.value?'DEV001':'')}
function cls(v:number):string{return classes.find(x=>x.value===v)?.label??String(v)}
function stateText(v:State):string{return states.find(x=>x.value===v)?.label??String(v)}
function nodeType(v:number):string{return({0:'作業站',1:'子流程',2:'模組',6:'AND 群組',7:'OR 群組',8:'開始',9:'結束'} as Record<number,string>)[v]??String(v)}
function dt(v:string):string{return v?v.replace('T',' ').slice(0,19).replaceAll('-','/') :''}
function persist():void{localStorage.setItem(storageKey,JSON.stringify(rows.value))}
function loadMock():void{try{const saved=localStorage.getItem(storageKey);rows.value=saved?JSON.parse(saved) as ProcessRow[]:copy(seed);if(!saved)persist()}catch{rows.value=copy(seed);persist()}}
const visible=computed(()=>rows.value.filter(r=>r.issueState===state.value&&[0,2,3].includes(r.processClass)&&(!keyword.value.trim()||r.processNo.toLowerCase().includes(keyword.value.trim().toLowerCase()))))
const active=computed(()=>rows.value.find(r=>key(r)===activeKey.value)??null),chosen=computed(()=>rows.value.filter(r=>selected.value.includes(key(r))))
const graphItems=computed(()=>active.value?.nodes.slice().sort((a,b)=>a.sequence-b.sequence)??[])
async function api<T>(path:string,init:RequestInit={}):Promise<T>{const headers=new Headers(init.headers);if(init.body&&!(init.body instanceof FormData)&&!headers.has('Content-Type'))headers.set('Content-Type','application/json');const res=await fetch(props.apiBaseUrl.replace(/\/+$/,'')+path,{credentials:'include',...init,headers});if(res.status===401){window.location.assign(import.meta.env.BASE_URL+'login');throw new Error('登入逾期，請重新登入。')}if(!res.ok){const b=await res.json().catch(()=>null) as Envelope<unknown>|null;throw new Error(b?.detail||b?.message||b?.title||'API 回應錯誤 ('+res.status+')。')}return res.status===204?undefined as T:await res.json() as T}
async function load():Promise<void>{busy.value=true;error.value='';try{if(mock.value)loadMock();else{const q=new URLSearchParams({issueState:String(state.value),processNo:keyword.value.trim()});const result=await api<ProcessRow[]|Envelope<ProcessRow>>('/api/process-basis?'+q);rows.value=Array.isArray(result)?result:result.items??result.rows??result.data??[]}if(!visible.value.some(r=>key(r)===activeKey.value))activeKey.value=visible.value[0]?key(visible.value[0]):'';selected.value=[];notice.value='資料筆數 '+visible.value.length}catch(e){error.value=e instanceof Error?e.message:'載入失敗。'}finally{busy.value=false}}
function select(r:ProcessRow):void{activeKey.value=key(r);selected.value=[key(r)]}
function toggle(r:ProcessRow):void{const k=key(r);selected.value=selected.value.includes(k)?selected.value.filter(x=>x!==k):[...selected.value,k];activeKey.value=k}
function open(next:Exclude<Mode,''>):void{const r=active.value;error.value='';if(next!=='add'&&!r){error.value='請先選取流程。';return}if(next==='edit'&&r?.issueState!==0){error.value='只有未核准流程可修改。';return}if(next==='version'&&!(r?.issueState===2&&r.curVersion===1)){error.value='只有目前版本的已核准流程可換版。';return}mode.value=next;sourceKey.value=r?key(r):'';if(next==='add')draft.value=blank();else if(next==='edit')draft.value={processNo:r!.processNo,processVersion:r!.processVersion,processClass:r!.processClass,processType:r!.processType,psNo:r!.psNo,description:r!.description};else if(next==='version')draft.value={processNo:r!.processNo,processVersion:/^\d{2}$/.test(r!.processVersion)?String(Number(r!.processVersion)+1).padStart(2,'0'):'',processClass:r!.processClass,processType:r!.processType,psNo:r!.psNo,description:r!.description};else draft.value={processNo:'',processVersion:'01',processClass:r!.processClass,processType:r!.processType,psNo:r!.psNo,description:r!.description};editor.value=true}
function validate():string{const d=draft.value;if(!d.processNo.trim()||!d.processVersion.trim()||d.processClass===''||!d.processType||!d.psNo)return'流程編號、版本、類別、流程類別與生產區段皆必填。';if(d.processNo.length>30||d.processVersion.length>3||d.processType.length>20||d.psNo.length>50||d.description.length>255)return'欄位長度超過資料表限制。';if(/[&<>]/.test(d.processNo)||d.processNo.includes(',')||d.processVersion.includes(','))return'流程編號不可含 &、<、>、逗號；版本不可含逗號。';if(!segments.includes(d.psNo)||!types.includes(d.processType))return'請選已核准區段與流程類別。';if(rows.value.some(r=>r.processNo===d.processNo&&r.processVersion===d.processVersion&&!(mode.value==='edit'&&key(r)===sourceKey.value)))return'流程編號與版本已存在。';if(mode.value==='version'&&!/^\d{2}$/.test(d.processVersion))return'新版本須為兩位數字。';return''}
async function save(keep:boolean):Promise<void>{const msg=validate();if(msg){error.value=msg;return}const d=draft.value,src=rows.value.find(r=>key(r)===sourceKey.value);busy.value=true;error.value='';try{if(!mock.value){const body={...d,dataStamp:src?.dataStamp,fromProcessNo:src?.processNo,fromProcessVersion:src?.processVersion};const path=mode.value==='edit'?'/api/process-basis/'+encodeURIComponent(d.processNo)+'/'+encodeURIComponent(d.processVersion):(mode.value==='copy'||mode.value==='version')?'/api/process-basis/copy':'/api/process-basis';await api(path,{method:mode.value==='edit'?'PUT':'POST',body:JSON.stringify(body)});await load()}else if(mode.value==='edit'&&src){Object.assign(src,{processClass:Number(d.processClass),processType:d.processType,psNo:d.psNo,description:d.description,dataStamp:src.dataStamp+1,reviser:userNo(),reviseDate:new Date().toISOString()});persist()}else{const now=new Date().toISOString(),idMap=new Map<string,string>();if(src)src.nodes.forEach((n,i)=>idMap.set(n.nodeId,'DEV-'+Date.now()+'-'+i));if(src&&mode.value==='version')src.curVersion=0;const r:ProcessRow={...d,processClass:Number(d.processClass),issueState:0,curVersion:0,tuningProcess:0,partialType:0,dataStamp:0,creator:userNo(),createDate:now,reviser:'',reviseDate:'',nodes:src?src.nodes.map(n=>({...n,nodeId:idMap.get(n.nodeId)??n.nodeId})):[],links:src?src.links.map(l=>({...l,fromNodeId:idMap.get(l.fromNodeId)??l.fromNodeId,toNodeId:idMap.get(l.toNodeId)??l.toNodeId})):[],properties:src?copy(src.properties):[]};rows.value.push(r);activeKey.value=key(r);state.value=0;persist()}if(keep&&(mode.value==='add'||mode.value==='copy')){draft.value={...blank(),processClass:Number(d.processClass),processType:d.processType,psNo:d.psNo};notice.value='開發假資料已新增；表單保持開啟。'}else{editor.value=false;notice.value=mock.value?'開發假資料已更新。':'已儲存。'}}catch(e){error.value=e instanceof Error?e.message:'儲存失敗。'}finally{busy.value=false}}
async function del():Promise<void>{if(!chosen.value.length&&active.value)selected.value=[key(active.value)];if(!chosen.value.length){error.value='請先選取流程。';return}if(chosen.value.some(r=>r.issueState===1)){error.value='簽核中流程不可刪除。';return}if(!window.confirm('確定刪除選取流程？'))return;try{for(const r of chosen.value.slice()){if(!mock.value)await api('/api/process-basis/'+encodeURIComponent(r.processNo)+'/'+encodeURIComponent(r.processVersion),{method:'DELETE',body:JSON.stringify({issueState:r.issueState,dataStamp:r.dataStamp})});else if(r.issueState===2){r.issueState=-1;r.curVersion=0;r.dataStamp++}else rows.value=rows.value.filter(x=>key(x)!==key(r))}if(mock.value)persist();await load();notice.value=mock.value?'假資料已刪除／標記不使用。':'刪除完成。'}catch(e){error.value=e instanceof Error?e.message:'刪除失敗。'}}
async function approve():Promise<void>{const list=chosen.value.length?chosen.value:active.value?[active.value]:[];if(!list.length||list.some(r=>r.issueState!==0)){error.value='請選取未核准流程。';return}const noGraph=list.find(r=>!r.nodes.length);if(noGraph){error.value=noGraph.processNo+' 尚無流程圖，不能核准。';return}if(!window.confirm('送出選取流程核准？'))return;try{if(!mock.value){for(const r of list)await api('/api/process-basis/'+encodeURIComponent(r.processNo)+'/'+encodeURIComponent(r.processVersion)+'/approve',{method:'POST',body:JSON.stringify({dataStamp:r.dataStamp})});await load()}else{for(const r of list){if(r.processNo==='DEV-PRS-100'&&!window.confirm('DEV-PRODUCT-01 尚缺 OP-QC 參數；仍要繼續？'))return;rows.value.filter(x=>x.processNo===r.processNo&&x.curVersion===1).forEach(x=>x.curVersion=0);r.issueState=2;r.curVersion=1;r.dataStamp++;r.reviser=userNo();r.reviseDate=new Date().toISOString()}persist();await load()}notice.value=mock.value?'已模擬核准；正式簽核使用共用 Issue Job。':'已送交共用簽核流程。'}catch(e){error.value=e instanceof Error?e.message:'核准失敗。'}}
function openGraph():void{if(!active.value){error.value='請先選取流程。';return}if(active.value.issueState!==0){error.value='只有未核准流程可編輯流程圖。';return}graphNodes.value=copy(active.value.nodes);graphLinks.value=copy(active.value.links);graph.value=true}
function removeGraphNode(index:number):void{const id=graphNodes.value[index]?.nodeId;graphNodes.value.splice(index,1);graphLinks.value=graphLinks.value.filter(l=>l.fromNodeId!==id&&l.toNodeId!==id)}
function saveGraph():void{if(graphNodes.value.some(n=>!n.nodeNo.trim())||new Set(graphNodes.value.map(n=>n.nodeNo)).size!==graphNodes.value.length){error.value='節點編號不可空白或重複。';return}if(!mock.value){error.value='舊 MES 的 iMESXMLFlow 專屬 XML serializer 尚未提供，未寫正式資料。';return}if(active.value){active.value.nodes=copy(graphNodes.value);active.value.links=copy(graphLinks.value);active.value.dataStamp++;persist()}graph.value=false;notice.value='DEV 流程圖已存於 localStorage。'}
function openProps():void{if(!active.value){error.value='請先選取流程。';return}propertyRows.value=copy(active.value.properties);propertyDraft.value=null;propertySource.value='';properties.value=true}
function editProperty(item?:PropertyRow):void{propertySource.value=item?.propertyNo??'';propertyDraft.value=item?copy(item):{propertyNo:'',defaultValue:'',sequence:0,description:'',issueState:0,dataStamp:0}}
function removeProperty():void{if(propertyDraft.value)propertyRows.value=propertyRows.value.filter(p=>p.propertyNo!==propertyDraft.value?.propertyNo);propertyDraft.value=null}
function saveProp():void{const p=propertyDraft.value;if(!p)return;if(!elements.includes(p.propertyNo)||p.propertyNo.length>20||p.defaultValue.length>255||p.description.length>255||p.sequence<0||p.sequence>99){error.value='Property 必須選核准 Element，並符合欄長及 0–99 順序。';return}if(propertySource.value!==p.propertyNo&&propertyRows.value.some(x=>x.propertyNo===p.propertyNo)){error.value='PropertyNo 已存在。';return}const i=propertyRows.value.findIndex(x=>x.propertyNo===propertySource.value);if(i<0)propertyRows.value.push(copy(p));else propertyRows.value[i]=copy(p);propertySource.value=p.propertyNo;propertyDraft.value=null}
function saveProps():void{if(!active.value)return;if(!mock.value){error.value='流程屬性 API 尚未提供，未寫入正式資料。';return}active.value.properties=copy(propertyRows.value);persist();properties.value=false;notice.value='DEV 流程屬性已更新。'}
function openImport():void{importing.value=true;fileName.value='';importMessage.value=''}
function pickFile(e:Event):void{fileName.value=(e.target as HTMLInputElement).files?.[0]?.name??'';importMessage.value=''}

async function doImport():Promise<void>{if(!fileName.value){importMessage.value='請選 .xls/.xlsx 檔案。';return}if(mock.value){importMessage.value='原 WinForms 使用 NPOI 和 ProcessDataChecker；DEV 未解析 Excel，不會假裝匯入成功。';return}const f=document.querySelector<HTMLInputElement>('#prs104-file')?.files?.[0];if(!f)return;const body=new FormData();body.append('file',f);try{const r=await api<{message?:string}>('/api/process-basis/import',{method:'POST',body});importMessage.value=r.message??'匯入完成';await load()}catch(e){importMessage.value=e instanceof Error?e.message:'匯入失敗'}}
function openExclude():void{if(!active.value){error.value='請先選取流程。';return}excluding.value=true}
onMounted(load)
</script>
<template>
<main class="prs104">
<header class="heading"><div><h1>流程基本資料</h1><small>流程設定 / PRS BASIS / PS104</small></div><b v-if="mock" class="dev">開發假資料</b><button @click="emit('close')">關閉</button></header>
<p v-if="mock" class="devnote">使用本機 localStorage 假資料；不寫正式資料庫。流程圖為 DEV 結構，不相容舊 MES XML。</p>
<section class="query"><div class="states"><label v-for="s in states" :key="s.value"><input v-model="state" type="radio" :value="s.value" @change="load">{{s.label}}</label></div><label>流程編號 <input v-model="keyword" maxlength="30" @keyup.enter="load"></label><button class="primary" @click="load">查詢</button></section>
<p v-if="error" class="feedback err">{{error}}</p><p v-else-if="notice" class="feedback">{{notice}}</p>
<section class="layout"><div class="tablewrap"><table><thead><tr><th></th><th>Process No</th><th>Process Version</th><th>Cur. Version</th><th>Process Class</th><th>Process Type</th><th>PS. No</th><th>Description</th><th>Creator</th><th>CreateDate</th><th>Reviser</th><th>ReviseDate</th></tr></thead><tbody>
<tr v-for="r in visible" :key="key(r)" :class="{active:key(r)===activeKey}" @click="select(r)"><td><input type="checkbox" :checked="selected.includes(key(r))" @click.stop="toggle(r)"></td><td>{{r.processNo}}</td><td>{{r.processVersion}}</td><td>{{r.curVersion?'是':'否'}}</td><td>{{cls(r.processClass)}}</td><td>{{r.processType}}</td><td>{{r.psNo}}</td><td>{{r.description}}</td><td>{{r.creator}}</td><td>{{dt(r.createDate)}}</td><td>{{r.reviser}}</td><td>{{dt(r.reviseDate)}}</td></tr><tr v-if="!visible.length"><td colspan="12" class="empty">{{busy?'載入中…':'查無資料'}}</td></tr>
</tbody></table></div><aside class="actions"><button class="primary" @click="open('add')">新增 (A)</button><button :disabled="!active||active.issueState!==0" @click="open('edit')">修改 (E)</button><button :disabled="!active" @click="open('copy')">複製 (C)</button><button @click="approve">核准</button><button @click="del">刪除 (D)</button><button :disabled="!active" @click="openProps">Property (S)</button><button :disabled="!active||active.issueState!==2||active.curVersion!==1" @click="open('version')">版本 (V)</button><button :disabled="!active" @click="openExclude">Exclude OP</button><button :disabled="!active||active.issueState!==0" @click="openGraph">Draw</button></aside></section>
<section class="preview"><div class="subhead"><div><b>流程圖預覽</b><small>{{active?active.processNo+' / '+active.processVersion+'　節點 '+active.nodes.length+' 個':'未選取流程'}}</small></div><button :disabled="!active||active.issueState!==0" @click="openGraph">Draw</button></div><div class="nodes"><div v-for="(n,i) in graphItems" :key="n.nodeId" class="node"><small>{{nodeType(n.nodeType)}}</small><b>{{n.nodeNo}}</b><span>{{n.description||n.stageNo}}</span><i v-if="i<graphItems.length-1">→</i></div><span v-if="!graphItems.length" class="empty">選取流程後顯示節點。</span></div></section>
<footer class="count">資料總筆數 {{visible.length}}<span v-if="active">　{{stateText(active.issueState)}}　DataStamp {{active.dataStamp}}</span><button @click="openImport">Import</button><small>APS Integration（舊畫面預設隱藏）</small></footer>

<div v-if="editor" class="shade" @click.self="editor=false"><section class="dialog"><header><h2>流程基本資料（{{mode==='add'?'新增':mode==='edit'?'修改':mode==='copy'?'複製':'版本'}}）</h2><button @click="editor=false">×</button></header><div class="form">
<label>流程編號<input v-model.trim="draft.processNo" maxlength="30" :readonly="mode==='edit'||mode==='version'"></label><label>流程版本<input v-model.trim="draft.processVersion" maxlength="3" :readonly="mode==='edit'"></label>
<label>流程類別<select v-model="draft.processClass" :disabled="mode==='edit'"><option v-for="c in classes" :key="c.value" :value="c.value">{{c.label}}</option></select></label><label>生產區段<select v-model="draft.psNo" :disabled="mode==='edit'||mode==='version'"><option value="">請選擇</option><option v-for="v in segments" :key="v">{{v}}</option></select></label><label>流程類別代碼<select v-model="draft.processType" :disabled="mode==='edit'||mode==='version'"><option value="">請選擇</option><option v-for="v in types" :key="v">{{v}}</option></select></label><label class="wide">說明<textarea v-model="draft.description" maxlength="255"></textarea></label></div><p class="audit">建立人：{{mode==='edit'?active?.creator:userNo()}}　建立日期：{{mode==='edit'?dt(active?.createDate||''):dt(new Date().toISOString())}}　修改人：{{mode==='edit'?userNo():'—'}}</p><p v-if="error" class="feedback err">{{error}}</p><footer><button class="primary" @click="save(false)">確定</button><button @click="save(true)">套用</button><button @click="editor=false">關閉</button></footer></section></div>

<div v-if="graph" class="shade" @click.self="graph=false"><section class="dialog wide"><header><h2>流程圖編輯</h2><button @click="graph=false">×</button></header><p class="devnote">舊 MES 用 iMESXMLFlow 專屬 XML；此簡化 DEV 編輯器不宣稱相容。群組、分支排版及 serializer 待家用端處理。</p><button @click="graphNodes.push({nodeId:'DEV-'+Date.now(),nodeNo:'NEW-OP',nodeType:0,description:'',stageNo:'',sequence:graphNodes.length+1})">新增節點</button><button @click="graphLinks.push({fromNodeId:'',toNodeId:'',linkName:''})">新增連線</button><div v-for="(n,i) in graphNodes" :key="n.nodeId" class="nodeedit"><select v-model.number="n.nodeType"><option :value="8">開始</option><option :value="0">作業站</option><option :value="1">子流程</option><option :value="2">模組</option><option :value="6">AND 群組</option><option :value="7">OR 群組</option><option :value="9">結束</option></select><input v-model="n.nodeNo" placeholder="NodeNo"><input v-model="n.description" placeholder="說明"><input v-model="n.stageNo" placeholder="StageNo"><input v-model.number="n.sequence" type="number"><button @click="removeGraphNode(i)">刪除</button></div><div v-for="(link,i) in graphLinks" :key="'link-'+i" class="nodeedit"><select v-model="link.fromNodeId"><option value="">來源節點</option><option v-for="n in graphNodes" :key="n.nodeId" :value="n.nodeId">{{n.nodeNo}}</option></select><select v-model="link.toNodeId"><option value="">目標節點</option><option v-for="n in graphNodes" :key="n.nodeId" :value="n.nodeId">{{n.nodeNo}}</option></select><input v-model="link.linkName" placeholder="LinkName"><button @click="graphLinks.splice(i,1)">刪除連線</button></div><footer><button class="primary" @click="saveGraph">儲存 DEV 圖</button><button @click="graph=false">關閉</button></footer></section></div>

<div v-if="properties" class="shade" @click.self="properties=false"><section class="dialog wide"><header><h2>流程屬性 {{active?.processNo}} / {{active?.processVersion}}</h2><button @click="properties=false">×</button></header><table class="propgrid"><thead><tr><th>Property No</th><th>DefaultValue</th><th>Sequence</th><th>Description</th><th>狀態</th></tr></thead><tbody><tr v-for="p in propertyRows" :key="p.propertyNo" @click="editProperty(p)"><td>{{p.propertyNo}}</td><td>{{p.defaultValue}}</td><td>{{p.sequence}}</td><td>{{p.description}}</td><td>{{stateText(p.issueState)}}</td></tr></tbody></table><button @click="editProperty()">新增</button><button :disabled="!propertyDraft" @click="removeProperty">刪除選取</button><div v-if="propertyDraft" class="form"><label>Property No<select v-model="propertyDraft.propertyNo"><option value="">請選擇</option><option v-for="e in elements" :key="e">{{e}}</option></select></label><label>預設值<input v-model="propertyDraft.defaultValue" maxlength="255"></label><label>順序<input v-model.number="propertyDraft.sequence" type="number" min="0" max="99"></label><label>說明<input v-model="propertyDraft.description" maxlength="255"></label><button @click="saveProp">套用到清單</button></div><p v-if="error" class="feedback err">{{error}}</p><footer><button class="primary" @click="saveProps">儲存</button><button @click="properties=false">關閉</button></footer></section></div>

<div v-if="importing" class="shade" @click.self="importing=false"><section class="dialog"><header><h2>流程資料匯入</h2><button @click="importing=false">×</button></header><p>舊 WinForms 接受單一 .xls/.xlsx，逐流程列出 ProcessNo、Version 和執行訊息。</p><input id="prs104-file" type="file" accept=".xls,.xlsx" @change="pickFile"><p>{{fileName||'尚未選取檔案'}}</p><p class="devnote">{{importMessage||'DEV 原型未假裝完成 Excel 解析。'}}</p><footer><button @click="importMessage='正式範本由 API 依系統檔案設定下載；DEV 未連範本服務。'">下載範本</button><button class="primary" :disabled="!fileName" @click="doImport">匯入</button><button @click="importing=false">關閉</button></footer></section></div>
<div v-if="excluding" class="shade" @click.self="excluding=false"><section class="dialog wide"><header><h2>Exclude OP　{{active?.processNo}} / {{active?.processVersion}}</h2><button @click="excluding=false">×</button></header><p>顯示產品流程已引用、但產品作業資料缺少的流程節點。</p><table class="propgrid"><thead><tr><th>Type</th><th>ProductNo</th><th>ProductVersion</th><th>ProcessVersion</th><th>NodeNo</th></tr></thead><tbody><tr v-if="active?.processNo==='DEV-PRS-100'"><td>Product</td><td>DEV-PRODUCT-01</td><td>01</td><td>*</td><td>OP-QC</td></tr><tr v-else><td colspan="5">無缺少節點的 DEV 假資料</td></tr></tbody></table><footer><button class="primary" @click="excluding=false">關閉</button></footer></section></div>
</main>
</template>
